/// <reference lib="webworker" />
import { cleanupOutdatedCaches, precacheAndRoute } from 'workbox-precaching';

declare let self: ServiceWorkerGlobalScope;

// Clean up previous caches
cleanupOutdatedCaches();

// Precache static assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST || []);

// Immediately take control of clients
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

/**
 * Handle incoming push notifications
 * Specifically tailored for DAR approval status updates, GM reviews, and urgent showroom alerts
 */
self.addEventListener('push', (event: PushEvent) => {
  let data = {
    title: 'DAR Approval Status Update',
    body: 'Your Daily Activity Report has been reviewed by the General Manager.',
    icon: '/pwa-192x192.png',
    badge: '/pwa-192x192.png',
    tag: 'dar-approval-notification',
    url: '/?tab=dar',
    reportId: '',
    status: 'Approved',
    timestamp: Date.now(),
  };

  if (event.data) {
    try {
      const parsed = event.data.json();
      data = { ...data, ...parsed };
    } catch {
      data.body = event.data.text() || data.body;
    }
  }

  const notificationTitle = data.title || 'AutoCRM DAR Alert';
  const notificationOptions: NotificationOptions & { vibrate?: number[]; actions?: Array<{ action: string; title: string }> } = {
    body: data.body,
    icon: data.icon || '/pwa-192x192.png',
    badge: data.badge || '/pwa-192x192.png',
    tag: data.tag || `dar-alert-${Date.now()}`,
    data: {
      url: data.url || '/?tab=dar',
      reportId: data.reportId,
      status: data.status,
      timestamp: data.timestamp || Date.now(),
    },
    vibrate: [200, 100, 200, 100, 250],
    requireInteraction: true,
    actions: [
      { action: 'view_dar', title: '📄 View DAR' },
      { action: 'dismiss', title: 'Dismiss' },
    ],
  };

  event.waitUntil(
    self.registration.showNotification(notificationTitle, notificationOptions as any)
  );
});

/**
 * Handle notification clicks: focus open window or navigate to DAR tab
 */
self.addEventListener('notificationclick', (event: NotificationEvent) => {
  event.notification.close();

  if (event.action === 'dismiss') {
    return;
  }

  const notificationData = event.notification.data || {};
  const targetUrl = notificationData.url || '/?tab=dar';

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      // If a tab is already open, focus it and broadcast event
      for (const client of clientList) {
        if ('focus' in client) {
          client.postMessage({
            type: 'NOTIFICATION_CLICKED',
            url: targetUrl,
            reportId: notificationData.reportId,
            status: notificationData.status,
          });
          return client.focus();
        }
      }
      // If no window open, open new window
      if (self.clients.openWindow) {
        return self.clients.openWindow(targetUrl);
      }
    })
  );
});

/**
 * Handle direct postMessage from main thread (e.g. simulation or in-app triggers)
 */
self.addEventListener('message', (event: ExtendableMessageEvent) => {
  if (event.data && event.data.type === 'SHOW_DAR_NOTIFICATION') {
    const { title, body, reportId, status, gmRemarks } = event.data;
    const notificationTitle = title || `DAR ${status}: Approval Status Update`;
    const notificationBody =
      body ||
      (status === 'Approved'
        ? `Great job! Your Daily Activity Report has been approved by GM. Remarks: "${gmRemarks || 'Target exceeded'}"`
        : `Your DAR requires revisions. Remarks: "${gmRemarks || 'Please verify hourly counts'}"`);

    self.registration.showNotification(notificationTitle, {
      body: notificationBody,
      icon: '/pwa-192x192.png',
      badge: '/pwa-192x192.png',
      tag: `dar-${reportId || Date.now()}`,
      vibrate: [200, 100, 200],
      requireInteraction: true,
      data: {
        url: '/?tab=dar',
        reportId,
        status,
        timestamp: Date.now(),
      },
      actions: [
        { action: 'view_dar', title: '📄 Open DAR' },
        { action: 'dismiss', title: 'Dismiss' },
      ],
    } as any);
  } else if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});
